import os
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


class StructuredDocumentExtractionError(ValueError):
    pass


def _get_field_value(field: Any) -> Any:
    if field is None:
        return None
    for attr in ("content", "value", "value_string", "value_date", "value_time", "value_currency", "value_number"):
        if hasattr(field, attr):
            val = getattr(field, attr)
            if val is not None:
                return val
    return field


def _get_field_confidence(field: Any) -> Optional[float]:
    if field is None:
        return None
    confidence = getattr(field, "confidence", None)
    if confidence is not None:
        try:
            return float(confidence)
        except (TypeError, ValueError):
            return None
    return None


def _normalize_result(result: Any) -> Dict[str, Any]:
    documents = []
    for doc in getattr(result, "documents", []) or []:
        fields = {}
        raw_fields = getattr(doc, "fields", {}) or {}
        if isinstance(raw_fields, dict):
            items = raw_fields.items()
        else:
            items = []
        for name, field in items:
            fields[name] = {
                "value": _get_field_value(field),
                "confidence": _get_field_confidence(field),
            }
        documents.append(
            {
                "doc_type": getattr(doc, "doc_type", None),
                "confidence": getattr(doc, "confidence", None),
                "fields": fields,
            }
        )

    pages = []
    for page in getattr(result, "pages", []) or []:
        pages.append(
            {
                "page_number": getattr(page, "page_number", None),
                "width": getattr(page, "width", None),
                "height": getattr(page, "height", None),
                "unit": getattr(page, "unit", None),
            }
        )

    return {
        "model_id": getattr(result, "model_id", None),
        "content": getattr(result, "content", None),
        "documents": documents,
        "pages": pages,
        "raw": result,
    }


def extract_invoice_structured(
    document_bytes: bytes,
    *,
    required_fields: Optional[List[str]] = None,
    min_confidence: float = 0.8,
    model_id: str = "prebuilt-invoice",
) -> Dict[str, Any]:
    """
    Extracts invoice data using Azure Document Intelligence and validates required fields/confidence.

    Environment variables:
      - AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT
      - AZURE_DOCUMENT_INTELLIGENCE_KEY
    """
    endpoint = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint:
        raise StructuredDocumentExtractionError("Missing AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    if not key:
        raise StructuredDocumentExtractionError("Missing AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if required_fields is None:
        required_fields = [
            "VendorName",
            "InvoiceId",
            "InvoiceDate",
            "DueDate",
            "AmountDue",
        ]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))
    poller = client.begin_analyze_document(model_id=model_id, body=document_bytes)
    result = poller.result()

    normalized = _normalize_result(result)

    if not normalized["documents"]:
        raise StructuredDocumentExtractionError("No structured documents returned by Azure Document Intelligence")

    primary_doc = normalized["documents"][0]
    fields = primary_doc.get("fields", {})

    missing_fields: List[str] = []
    low_confidence_fields: Dict[str, float] = {}

    for field_name in required_fields:
        field_data = fields.get(field_name)
        if not field_data or field_data.get("value") in (None, ""):
            missing_fields.append(field_name)
            continue

        confidence = field_data.get("confidence")
        if confidence is None or confidence < min_confidence:
            low_confidence_fields[field_name] = confidence if confidence is not None else -1.0

    if missing_fields or low_confidence_fields:
        raise StructuredDocumentExtractionError(
            {
                "message": "Validation failed for required structured fields and confidence scores",
                "missing_fields": missing_fields,
                "low_confidence_fields": low_confidence_fields,
                "min_confidence": min_confidence,
                "required_fields": required_fields,
            }
        )

    return {
        "validated": True,
        "min_confidence": min_confidence,
        "required_fields": required_fields,
        "document": primary_doc,
        "result": normalized,
    }
